"use strict";(self.webpackChunkcanva_connect=self.webpackChunkcanva_connect||[]).push([[298],{2792(e,t,o){o.r(t),o.d(t,{_pageData:()=>l,default:()=>d});var n=o(641),a=o(483),r=o(2988),s=o(4387);const i=[(0,n.Fv)('<h1 id="canva-developer-portal-configuration" tabindex="-1"><a class="header-anchor" href="#canva-developer-portal-configuration"><span>Canva Developer Portal &amp; Configuration</span></a></h1><p>Follow these steps to create your Canva Developer App, generate OAuth credentials, upload the app bundle, configure WooCommerce settings, manage CORS headers, and configure WordPress permalinks.</p><hr><h2 id="step-1-create-an-app-in-canva-developer-portal" tabindex="-1"><a class="header-anchor" href="#step-1-create-an-app-in-canva-developer-portal"><span>Step 1: Create an App in Canva Developer Portal</span></a></h2><ul><li><strong>What to click:</strong> Visit the <a href="https://www.canva.com/developers/" target="_blank" rel="noopener noreferrer">Canva Developer Portal</a>, log in to your Canva account, click <strong>Your apps</strong>, and click <strong>Create an app</strong>.</li><li><strong>What to enter:</strong> Enter your app name (e.g., <em>Webkul App</em> or <em>My Store Canva Connector</em>).</li><li><strong>What to copy:</strong> Copy the generated <strong>App ID</strong> (starts with <code>AAHOG...</code>).</li><li><strong>Expected result:</strong> Your Canva App is created and assigned a unique App ID used for token validation.</li></ul><hr><h2 id="step-2-create-integration-oauth-credentials" tabindex="-1"><a class="header-anchor" href="#step-2-create-integration-oauth-credentials"><span>Step 2: Create Integration &amp; OAuth Credentials</span></a></h2><ul><li><strong>What to click:</strong> In the Canva Developer Portal, switch to the <strong>Your integrations</strong> tab and click <strong>Create an integration</strong>.</li><li><strong>What to do:</strong><ol><li>Under <strong>Configuration</strong>, copy the <strong>Client ID</strong> (starts with <code>OC-...</code>).</li><li>Click <strong>Generate secret</strong> to generate and copy the <strong>Client Secret</strong>.</li><li>In the <strong>Scopes</strong> tab, enable the required permissions: <ul><li><code>design:content:read</code></li><li><code>design:content:write</code></li><li><code>design:meta:read</code></li><li><code>asset:read</code></li><li><code>asset:write</code></li></ul></li></ol></li><li><strong>Expected result:</strong> OAuth 2.0 credentials and permissions are created for your store.</li></ul><hr><h2 id="step-3-upload-app-bundle-code-upload" tabindex="-1"><a class="header-anchor" href="#step-3-upload-app-bundle-code-upload"><span>Step 3: Upload App Bundle (Code Upload)</span></a></h2><ul><li><strong>What to click:</strong> In your Canva App settings, navigate to <strong>Build &gt; Inside Canva &gt; Code upload</strong> (or <strong>App source</strong>).</li><li><strong>What to do:</strong><ol><li>Select <strong>JavaScript bundle</strong>.</li><li>Click <strong>Choose file</strong> and upload your compiled <code>dist/app.js</code> bundle (maximum size 5MB).</li><li>Under <strong>Translations</strong>, upload your language file (e.g., <code>messages_en.json</code>) if needed.</li></ol></li><li><strong>Expected result:</strong> The bundle is uploaded, registering the Webkul App inside the Canva editor&#39;s left panel.</li></ul><p><a class="doc-image-link" href="./assets/canva-developer-portal-code-upload.png"><img src="'+a+'" alt="Canva Developer Portal Code Upload and App Identifiers"></a></p><hr><h2 id="step-4-configure-woocommerce-canva-connect-settings" tabindex="-1"><a class="header-anchor" href="#step-4-configure-woocommerce-canva-connect-settings"><span>Step 4: Configure WooCommerce Canva Connect Settings</span></a></h2><ul><li><strong>What to click:</strong> In your WordPress Admin, go to <strong>Webkul WC Addons &gt; Canva Connect</strong>.</li><li><strong>What to enter:</strong><ol><li><strong>App ID:</strong> Paste the App ID copied from Canva Developer Portal.</li><li><strong>Client ID:</strong> Paste the Client ID from your Canva Integration.</li><li><strong>Client Secret:</strong> Paste the Client Secret.</li></ol></li><li><strong>What to copy &amp; paste into Canva:</strong><ul><li>Copy the <strong>Redirect URI</strong> displayed at the bottom (<code>https://your-domain.com/wp-json/canva/v1/callback</code>) and paste it into the <strong>Redirect URI</strong> field of your Canva Integration.</li><li>Copy the <strong>Return URL</strong> (<code>https://your-domain.com/wp-json/canva/v1/return</code>) and paste it into the <strong>Return Navigation URL</strong> field in Canva.</li></ul></li><li><strong>What to click:</strong> Click <strong>Save Settings</strong>.</li><li><strong>Expected result:</strong> WordPress securely stores the credentials and the OAuth handshake is established.</li></ul><p><a class="doc-image-link" href="./assets/canva-connect-admin-settings.png"><img src="'+r+'" alt="Canva Connect Settings in WooCommerce Admin"></a></p><hr><h2 id="step-5-cors-headers-https-setup" tabindex="-1"><a class="header-anchor" href="#step-5-cors-headers-https-setup"><span>Step 5: CORS Headers &amp; HTTPS Setup</span></a></h2><ul><li><strong>HTTPS Requirement:</strong> Your WordPress store must have a valid SSL certificate (<code>https://</code>). Canva will reject unsecured <code>http://</code> API requests.</li><li><strong>Disable CORS Headers Checkbox:</strong><ul><li><strong>Leave unchecked (Default):</strong> The plugin automatically manages and sends required CORS headers (<code>Access-Control-Allow-Origin: *</code>, <code>Authorization</code>, <code>Content-Type</code>) for Canva editor iframe requests.</li><li><strong>Check the box only if:</strong> Your web server (Nginx/Apache/Cloudflare) already injects its own <code>Access-Control-Allow-Origin</code> header to avoid duplicate header conflicts.</li></ul></li><li><strong>Expected result:</strong> Cross-origin communication between the Canva editor sandbox and your WooCommerce REST API operates smoothly without browser errors.</li></ul><hr><h2 id="step-6-configure-wordpress-permalinks" tabindex="-1"><a class="header-anchor" href="#step-6-configure-wordpress-permalinks"><span>Step 6: Configure WordPress Permalinks</span></a></h2><ul><li><strong>What to click:</strong> Go to <strong>Settings &gt; Permalinks</strong> in your WordPress Admin.</li><li><strong>What to select:</strong> Under <em>Common Settings</em>, select <strong>Post name</strong> (<code>/%postname%/</code>).</li><li><strong>What to click:</strong> Click <strong>Save Changes</strong>.</li><li><strong>Expected result:</strong> WordPress permalinks are flushed, ensuring all <code>/wp-json/canva/v1/*</code> REST API endpoints route properly.</li></ul><p><a class="doc-image-link" href="./assets/permalinks.webp"><img src="'+s+'" alt="WordPress Permalinks Post Name Setting"></a></p>',23)],l=JSON.parse('{"path":"/documentation/how-to-part-2.html","title":"Canva Developer Portal & Configuration","lang":"en-US","frontmatter":{"title":"Canva Developer Portal & Configuration"},"git":{},"filePathRelative":"documentation/how-to-part-2.md"}'),c={name:"how-to-part-2.md"},d=(0,o(6262).A)(c,[["render",function(e,t,o,a,r,s){return(0,n.uX)(),(0,n.CE)("div",null,i)}]])},2988(e,t,o){e.exports=o.p+"assets/img/canva-connect-admin-settings.bc263003.png"},483(e,t,o){e.exports=o.p+"assets/img/canva-developer-portal-code-upload.6b681036.png"},4387(e,t,o){e.exports=o.p+"assets/img/permalinks.178d2208.webp"}}]);